function getCity(user) {
  // This line crashes when some data is missing. Protect it.
  return user.address.city.toUpperCase();
}

console.log(getCity({ address: { city: "Madrid" } }));
console.log(getCity({ name: "Ana" }));

solution:
function getCity(user) {
  try {
    // If user, address or city is missing, this line
    // throws a TypeError and we jump to catch.
    return user.address.city.toUpperCase();
  } catch (e) {
    return "Unknown";
  }
}

console.log(getCity({ address: { city: "Madrid" } }));
console.log(getCity({ name: "Ana" }));

alternatives:
function getCity(user) {
  if (!user || !user.address || !user.address.city) {
    return "Unknown";
  }
  return user.address.city.toUpperCase();
}

console.log(getCity({ address: { city: "Madrid" } }));
console.log(getCity({ name: "Ana" }));
