starter:
function totalPrice(prices) {
  let total = 0;
  for (let i = 0; i < prices.length; i++) {
    total = prices[i];
  }
  return total;
}

console.log(totalPrice([5, 10, 3]));

solution:
function totalPrice(prices) {
  let total = 0;
  for (let i = 0; i < prices.length; i++) {
    // The bug was total = prices[i]: it replaced the total
    // on each turn instead of adding the new price to it.
    total += prices[i];
  }
  return total;
}

console.log(totalPrice([5, 10, 3]));

alternatives:
function totalPrice(prices) {
  let total = 0;
  for (const price of prices) {
    total = total + price;
  }
  return total;
}

console.log(totalPrice([5, 10, 3]));
